fn discover_from(
    executable_path: Option<OsString>,
    home: Option<OsString>,
    codex_home: Option<OsString>,
    working_directory: Option<PathBuf>,
) -> Option<Self> {
    use std::os::unix::fs::PermissionsExt;
    let executable_path = executable_path?;
    let binary = std::env::split_paths(&executable_path)
        .filter(|path| path.is_absolute())
        .map(|path| path.join("codex"))
        .find(|path| std::fs::metadata(path).is_ok_and(|metadata| metadata.is_file() && metadata.permissions().mode() & 0o111 != 0))?;
    let binary = std::fs::canonicalize(binary).ok()?;
    let home = directory(&PathBuf::from(home?)).ok()?;
    let codex_home = directory(&codex_home.map(PathBuf::from).unwrap_or_else(|| home.join(".codex"))).ok()?;
    let working_directory = directory(&working_directory?).ok()?;
    let environment = [
        "OPENAI_API_KEY", "HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "NO_PROXY",
        "http_proxy", "https_proxy", "all_proxy", "no_proxy",
        "SSL_CERT_FILE", "SSL_CERT_DIR", "XDG_RUNTIME_DIR", "DBUS_SESSION_BUS_ADDRESS",
        "XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_CACHE_HOME", "LANG", "LC_ALL",
    ].into_iter().filter_map(|name| std::env::var_os(name).map(|value| (OsString::from(name), value))).collect::<BTreeMap<_,_>>();
    let gate = Arc::new(Mutex::new(()));
    let account = Arc::new(Mutex::new(None));
    let mut bindings = BTreeMap::new();
    for (reference, label) in [("local-researcher", "研究员"), ("local-reviewer", "独立审阅员")] {
        bindings.insert(reference.to_owned(), Binding {
            public: CodexHomeBindingV1 { reference: reference.into(), label: label.into(), profile_origin: ProfileOrigin::OperatorMount },
            home: home.clone(), codex_home: codex_home.clone(), working_directory: working_directory.clone(),
            environment: environment.clone(), gate: gate.clone(), account: account.clone(),
        });
    }
    Some(Self { binary, executable_path, bindings })
}

